        address router = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        IUniswapV2Router02 routerContract = IUniswapV2Router02(router);
        address weth = routerContract.WETH();

        // Give attacker ETH
        vm.deal(attacker, 100 ether);

        // Record initial ETH balance
        uint256 initialEthBalance = attacker.balance;
        console.log('Initial attacker ETH:', initialEthBalance);

